import Foundation

// macOS-only (C#-д байхгүй): хэрэглэгчийн үйлдэлд robot хариу үзүүлэх дүрмүүд.
// AppKit-гүй, цэвэр логик — ActivityWatcher (DeskBot target) эдгээрийг дуудна.

/// Copy → ✓. Pasteboard-ийн агуулгыг огт уншихгүй; зөвхөн type-ийн нэрээр нууц үг гэх мэтийг алгасна.
public enum ClipboardPolicy {
    /// nspasteboard.org конвенц: password manager-ууд (1Password, Bitwarden…) эдгээрийг тавьдаг.
    public static let quietTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
    ]

    public static func shouldReact(types: [String]) -> Bool {
        !types.isEmpty && quietTypes.isDisjoint(with: types)
    }

    /// ✓ хэр удаан харагдах.
    public static let checkSeconds: TimeInterval = 1.2
}

/// Хэт ойр давтагдах reaction-ийг шүүнэ (⌘C-г дараалан дарах г.м.).
public struct ReactionThrottle: Sendable {
    public let minInterval: TimeInterval
    private var last: Date?

    public init(minInterval: TimeInterval) { self.minInterval = minInterval }

    public mutating func allow(now: Date) -> Bool {
        if let last, now.timeIntervalSince(last) < minInterval { return false }
        last = now
        return true
    }
}

/// Browser-ууд татаж дуусаагүй файлдаа тавьдаг өргөтгөл.
public enum DownloadFiles {
    /// Chrome/Edge/Brave `.crdownload`, Safari `.download` (bundle), Firefox `.part`, Opera `.opdownload`, бусад `.partial`.
    public static let partialExtensions: Set<String> = ["crdownload", "download", "part", "partial", "opdownload"]

    public static func isInProgress(_ fileName: String) -> Bool {
        guard !fileName.hasPrefix(".") else { return false } // нуугдмал файл (.DS_Store г.м.)
        let ext = (fileName as NSString).pathExtension.lowercased()
        return partialExtensions.contains(ext)
    }

    public static func anyInProgress(_ fileNames: [String]) -> Bool {
        fileNames.contains(where: isInProgress)
    }
}

/// Нээгдэж буй app-ууд (willLaunch → didLaunch). didLaunch ирэхгүй тохиолдолд `timeout`-оор цэвэрлэнэ.
public struct PendingLaunches: Sendable {
    public static let timeout: TimeInterval = 8
    private var started: [Int32: Date] = [:]

    public init() {}

    public var isEmpty: Bool { started.isEmpty }

    public mutating func begin(pid: Int32, now: Date) { started[pid] = now }
    public mutating func end(pid: Int32) { started.removeValue(forKey: pid) }

    /// Хугацаа хэтэрсэнийг хаяна. Хоосон болсон бол true.
    @discardableResult
    public mutating func prune(now: Date) -> Bool {
        started = started.filter { now.timeIntervalSince($0.value) < Self.timeout }
        return started.isEmpty
    }
}
